#include <iostream>

class Medida {
public:
    explicit Medida(int numero) : numero_{numero} {}
    int numero() const noexcept { return numero_; }
    void sustituir(int nuevo) noexcept { numero_ = nuevo; }
private:
    int numero_;
};
class MedidaIdentificada : public Medida {
public:
    MedidaIdentificada(int numero, int codigo);
    int codigo() const noexcept { return codigo_; }
private:
    int codigo_;
};
MedidaIdentificada::MedidaIdentificada(int numero, int codigo)
    : Medida{0}, codigo_{0} {
    // Inicializa la base y el codigo con los argumentos recibidos.
    (void)numero;
    (void)codigo;
}
void fijar(Medida& destino, int nuevo) noexcept {
    // Utiliza la interfaz publica de Medida para cambiar su numero.
    (void)destino;
    (void)nuevo;
}
class Ficha {
public:
    Ficha(int numero, int codigo) : medida_{numero}, codigo_{codigo} {}
    int numero() const noexcept { return medida_.numero(); }
    int codigo() const noexcept { return codigo_; }
    Medida obtener_medida() const { return medida_; }
private:
    Medida medida_;
    int codigo_;
};
int main() {
    int inicial = 0, codigo = 0, nuevo = 0;
    if (!(std::cin >> inicial >> codigo >> nuevo)) { return 1; }
    MedidaIdentificada dato{inicial, codigo};
    const Ficha ficha{inicial, codigo};
    const Medida& vista = dato;
    Medida& editable = dato;
    Medida* acceso = &dato;
    Medida copia = ficha.obtener_medida();
    std::cout << "Antes:" << vista.numero() << ";CodigoAntes:" << dato.codigo();
    fijar(editable, nuevo);
    fijar(copia, nuevo);
    std::cout << ";Vista:" << vista.numero() << ";Derivada:" << dato.numero()
              << ";Puntero:" << acceso->numero() << ";Codigo:" << dato.codigo()
              << ";MismaParte:" << (&vista == acceso) << ";Ficha:" << ficha.numero()
              << ";CodigoFicha:" << ficha.codigo() << ";Copia:" << copia.numero();
    return 0;
}

